\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    xlabel={$z$},
    ylabel={$x$},
    title={Cross-section at $y = 1$: Hyperbola},
    domain=1:3,
    samples=100,
    width=8cm,
    height=6cm,
    grid=major,
    axis equal image,
    xmin=-3, xmax=3,
]
% Upper branch (x > 0)
\addplot[green!70!black, thick, smooth] {sqrt(2*(x^2 - 1))};
% Lower branch (x < 0)
\addplot[green!70!black, thick, smooth, dashed] {-sqrt(2*(x^2 - 1))};
% Mirror for negative z
\addplot[green!70!black, thick, smooth, domain=-3:-1] {sqrt(2*(x^2 - 1))};
\addplot[green!70!black, thick, smooth, dashed, domain=-3:-1] {-sqrt(2*(x^2 - 1))};
\end{axis}
\end{tikzpicture}
\end{document}

